  const SUFFIX = '\n\nCRITICAL RULES FOR OUTPUT:\n- NO markdown code fences (no ```json or ```)\n- NO explanations, preambles, or postambles\n- NO text before or after the JSON\n- NO comments inside the JSON\n- Output must be ONLY valid JSON\n- Output MUST start with { or [\n- Output MUST end with } or ]';
  const fullPrompt = PREFIX + $json.prompt + SUFFIX;
  const sessionId = $json.workflow_session_id || 'session_default';
  const runtimeId = 'runtime_session_' + sessionId + '_' + Date.now();
  const payload = {
    prompt: fullPrompt,
    workflow_id: $json.workflow_id || 'workflow_default',
    client_id: $json.client_id || 'client_default',
    project_id: $json.project_id || 'project_default',
    workflow_session_id: sessionId,
    model: $json.model || 'global.anthropic.claude-haiku-4-5-20251001-v1:0',
    runtimeSessionId: runtimeId
  };
  if ($json.memory_id) payload.memory_id = $json.memory_id;
  if ($json.knowledge_base_id) payload.knowledge_base_id = $json.knowledge_base_id;
  if ($json.system_prompt) payload.system_prompt = $json.system_prompt;
  return JSON.stringify(payload);
})() }}

